import {
  Button,
  Select,
  Form,
  Input,
  Popover,
  notification,
  Row,
  Upload,
  Icon,
  message,
  DatePicker
} from 'antd'
import React from 'react'
import moment from 'moment-timezone'
import agentAction from '../../../../../redux/agent/actions'
import policyActions from '../../../../../../redux/policy/actions'
import { PATH_FOR_AGENT_FILE_UPLOAD } from '../../../constants'
import CircularLoader from '../../../../../../components/CircularLoader'
import refresh from '../../../../../../image/refresh.png'
import { connect } from 'react-redux'
import { ButtonContainer } from './index.style'

const { updateAgentCorePolicyStatus, resetAgentRedux, getAgentApplicationData } = agentAction
const { uploadPolicyFile, resetReduxState: policyResetReduxState } = policyActions
const Option = Select.Option

class ReactivatePolicy extends React.Component {
  constructor (props) {
    super(props)
    this.state = {
      updatePolicyStatusVisible: false,
      policyReactivateDocument: '',
      uploadingStatus: false,
      reactivationDate: null
    }
  }

  // state = {
  //   updatePolicyStatusVisible: false,
  //   policyReactivateDocument: '',
  //   uploadingStatus: false
  // }

  componentDidUpdate () {
    const { applicationId } = this.props
    const { agentCorePolicyUpdateMessage, uploadPolicyFileStatus } = this.props
    if (agentCorePolicyUpdateMessage === 'success') {
      notification.success({ message: 'Policy Activated Successfully!' })
      this.props.getAgentApplicationData({ applicationId })
      this.props.getAgentInsuranceData()
    } else if (agentCorePolicyUpdateMessage) {
      notification.error({ message: agentCorePolicyUpdateMessage })
    }
    if (agentCorePolicyUpdateMessage === 'success') {
      notification.success({ message: 'Policy Activated Successfully!' })
      this.props.getAgentApplicationData({ applicationId })
      this.props.getAgentInsuranceData()
    } else if (agentCorePolicyUpdateMessage) {
      notification.error({ message: agentCorePolicyUpdateMessage })
    }
    if (uploadPolicyFileStatus === 'success') {
      this.setState({
        policyReactivateDocument: this.props.uploadPolicyFileData.url,
        uploadingStatus: false
      })
      this.props.policyResetReduxState([
        'uploadPolicyFileStatus',
        'uploadPolicyFileData'
      ])
    }
    this.props.resetAgentRedux(['agentCorePolicyUpdateMessage', 'agentPolicyUpdateProvMessage'])
  }

  customRequest = ({ file }) => {
    const formData = new FormData()
    if (file.name) {
      const fileName = file.name.split('.')[0]
      formData.append('file', file)
      formData.append(
        'path',
        `${PATH_FOR_AGENT_FILE_UPLOAD}/${fileName}_${Date.parse(new Date())}`
      )
      formData.append('identifier', 'agent')
      this.props.uploadPolicyFile({ body: formData })
      this.setState({
        uploadingStatus: true
      })
    }
  };

  beforeUpload = (file) => {
    // file size validation for 10MB
    const isLt10M = file.size / 1024 / 1024 <= 10
    if (!isLt10M) {
      message.error('file must be smaller than 10MB!')
    }
    return isLt10M
  };

  handleSubmitPolicyStatus = (e) => {
    e.preventDefault()
    const { applicationId, agentPolicy, dataProfile, onPolicyUpdate } = this.props
    const { policyReactivateDocument, reactivationDate } = this.state
    this.props.form.validateFields((err, values) => {
      if (!err) {
        let remark = values.remark
        if (remark === 'Others') {
          remark = values.remarkText
        }
        const payload = {
          applicationId: applicationId,
          remark: remark,
          user_id: dataProfile.email,
          reactivation_document: policyReactivateDocument
        }
        // Only include reactivation_date if a date is selected
        if (reactivationDate && (moment.isMoment(reactivationDate) || reactivationDate instanceof Date)) {
          payload.reactivation_date = moment(reactivationDate).format('YYYY-MM-DD')
        }
        if (agentPolicy?.remark_details?.cancelled?.previous_policy_state === 'COMPLETED') {
          this.props.updateAgentCorePolicyStatus(payload)
        } else {
          this.props.updateAgentCorePolicyStatus(payload)
          notification.success({message: "success"})
          this.props.getAgentInsuranceData()
          // window.location.reload();
          onPolicyUpdate()
        }
        this.handleUpdatePolicyStatus(false)
      }
    })
  }

  handleReactivateReasonChange = (value) => {
    this.props.form.setFieldsValue({
      remark: value
    })
  }

  handleUpdatePolicyStatus = (updatePolicyStatusVisible) => {
    this.setState({ updatePolicyStatusVisible, policyReactivateDocument: '', reactivationDate: null })
  }

  handleReactivationDateChange = (date) => {
    this.setState({ reactivationDate: date })
  }

  render () {
    const { getFieldDecorator } = this.props.form
    const { updatePolicyStatusVisible, uploadingStatus } = this.state
    return (
      <div style={{ display: 'inline-block' }}>
        <Popover
          overlayStyle={{ maxWidth: '50vw' }}
          overlayClassName='popover-style'
          content={
            <Form name='basic' onSubmit={this.handleSubmitPolicyStatus}>
              <Form.Item
                label='Reason to Reactivate'
                name='remark'
              >{
                  getFieldDecorator('remark', {
                    rules: [{ required: true, message: 'Remark cannot be blank' }]
                  })(
                    <Select
                      placeholder='Reason to Reactivate'
                      onChange={this.handleReactivateReasonChange}
                    >
                      <Option value='Request from Customer'> Request from Customer </Option>
                      <Option value='Request from Agent'> Request from Agent </Option>
                      <Option value='Request from Marketing team'> Request from Marketing team </Option>
                      <Option value='Others'> Others </Option>
                    </Select>)
                }
              </Form.Item>
              <Form.Item
                label='Request Date'
                name='reactivationDate'
              >
                <DatePicker
                  format='YYYY-MM-DD'
                  value={this.state.reactivationDate}
                  onChange={this.handleReactivationDateChange}
                  style={{ width: '100%' }}
                  placeholder='Select reactivation date'
                />
              </Form.Item>
              {
                this.props.form.getFieldValue('remark') === 'Others' &&
                  <Form.Item
                    label=''
                    name='remarkText'
                  >
                    {
                      getFieldDecorator('remarkText', {
                        rules: [{ required: true, message: 'Remark cannot be blank' }]
                      })(<Input.TextArea />)
                    }
                  </Form.Item>
              }
              <Form.Item
                label='Upload Document'
                name='document'
              >
                {
                  getFieldDecorator('document', {
                    rules: [{ required: false, message: 'Document Required' }]
                  })(
                    this.state.policyReactivateDocument
                      ? (
                        <>
                          <div style={{ display: 'flex', width: '150px' }}>
                            <object
                              type='application/pdf'
                              data={this.state.policyReactivateDocument}
                              width={150}
                              height={150}
                              aria-label='Policy Doc Pdf'
                            />
                            <div style={{ display: 'flex', 'align-items': 'start', 'justify-items': 'start' }} onClick={() => this.setState({ policyReactivateDocument: '' })}>
                              <Icon type='close' />
                            </div>
                          </div>
                        </>
                        )
                      : (
                        <Upload
                          name='upload'
                          showUploadList={false}
                          customRequest={(data) => this.customRequest(data)}
                          listType='picture'
                          accept='.pdf, .jpg, .jpeg, .png'
                          beforeUpload={(file) => { return this.beforeUpload(file) }}
                        >
                          {
                            uploadingStatus
                              ? <CircularLoader isSpining />
                              : (
                                <Button>
                                  <Icon type='upload' /> Click to upload
                                </Button>
                                )
                          }
                        </Upload>)
                  )
                }
              </Form.Item>
              <p>
                Policies that have been canceled due to expiration will be
                reactivated only for policies that have been successfully paid.
                The policy status automatically changes to provisional_issued
                once you submit the form and will send a notification to the
                insured and insurance provider along with the reason.
              </p>
              <Form.Item>
                <Row type='flex' justify='center'>
                  <Button
                    style={{ marginRight: 8 }}
                    onClick={() => this.handleUpdatePolicyStatus(false)}
                  >
                    Cancel
                  </Button>
                  <Button type='primary' htmlType='submit'>
                    Submit
                  </Button>
                </Row>
              </Form.Item>
            </Form>
          }
          title='Reactivate Policy Cancelled'
          trigger='click'
          visible={updatePolicyStatusVisible}
          onVisibleChange={this.handleUpdatePolicyStatus}
        >
          <ButtonContainer>
            <Button type='primary' className='btn-activate'>
                <img src={refresh} className='btn-icon' alt='' />
                Reactivate Policy
            </Button>
            </ButtonContainer>
        </Popover>
      </div>
    )
  }
}

const wrapperReactivatePolicy = Form.create()(ReactivatePolicy)
export default connect(state => ({
  agentPolicyUpdateProvMessage: state.Agent.agentPolicyUpdateProvMessage,
  agentCorePolicyUpdateMessage: state.Agent.agentCorePolicyUpdateMessage,
  uploadPolicyFileLoading: state.Loading.UPLOAD_FILE,
  uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
  uploadPolicyFileData: state.Insurance.uploadPolicyFileData
}), {
  updateAgentCorePolicyStatus,
  getAgentApplicationData,
  resetAgentRedux,
  uploadPolicyFile,
  policyResetReduxState
})(wrapperReactivatePolicy)
