import React from 'react'
import { connect } from 'react-redux'
import {
  Row,
  Col,
  Table,
  Form
} from 'antd'
import moment from 'moment'
import { get as lodashGet } from 'lodash'
import LayoutContent from '../../../../components/utility/layoutContent'
import { FLEET_POLICY, MANUAL_ORDER } from '../constants'
import { isVNPath } from '../../../../helpers/utility'

class PolicyPaymentDetailCore extends React.Component {
  constructor (props) {
    super(props)
    this.currencyType = isVNPath() ? 'VND' : 'Rp.'
  }

  getStatusColor (status) {
    switch (status) {
      case 'ACTIVE':
        return '#2d9600'
      case 'PENDING':
        return '#ffe58f'
      case 'PENDING_EMAIL':
        return '#ffe58f'
      default:
        return ''
    }
  }

  renderInformation (header, detailData) {
    return (
      <Col span={6}>
        <span>{header}</span>
        <p>{detailData}</p>
      </Col>
    )
  }

  render () {
    this.currencyType = isVNPath() ? 'VND' : 'Rp'
    const { policyDetail } = this.props
    const isManualOfflineOrder = [MANUAL_ORDER, FLEET_POLICY].includes(lodashGet(policyDetail, 'request.protection_case', ''))
    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value'
      }
    ]

    const columnPolicyDetailsReq = [
      {
        name: <strong>Txn Ref</strong>,
        value: lodashGet(policyDetail, 'Payments[0].PaymentData[0].TxnRef', '-')
      }, {
        name: <strong>Txn Date</strong>,
        value: moment(lodashGet(policyDetail, 'Payments[0].PaymentData[0].TxnDate', '-')).format('YYYY-MM-DD')
      }, {
        name: <strong>Proposed Coverage Start Date</strong>,
        value: moment(lodashGet(policyDetail, 'Payments[0].CoverageStartDate', '-')).format('YYYY-MM-DD')
      },
      {
        name: <strong>Proposed Coverage End Date</strong>,
        value: moment(lodashGet(policyDetail, 'Payments[0].CoverageEndDate', '-')).format('YYYY-MM-DD')
      },
      {
        name: <strong>Total Sum Insured</strong>,
        value: <strong>{this.currencyType} {lodashGet(policyDetail, 'Request.total_sum_insured', '-')}</strong>
      },
    //   {
    //     name: <strong>Premium Rate</strong>,
    //     value: `${lodashGet(policyDetail, 'payment_detail.premium_rate', '-')}%`
    //   },
    //   {
    //     name: <strong>Base Premium</strong>,
    //     value: `${this.currencyType} ${lodashGet(policyDetail, (isManualOfflineOrder ? 'net_premium' : 'payment_detail.base_premium'), '-')}`
    //   },
    //   ...(
    //     isManualOfflineOrder
    //       ? []
    //       : [{
    //           name: <strong>Addons Premium</strong>,
    //           value: `${this.currencyType} ${lodashGet(policyDetail, 'payment_detail.add_ons_premium', '-')}`
    //         }]
    //   ),
      ...(
        lodashGet(policyDetail, 'EndorsementStatus', '') !== 'NOT REQUIRED'
          ? [
            //   {
            //     name: <a href='#endorsement_detail'><strong>Premium Changes after endorsement (exclude discount)</strong></a>,
            //     value: <a href='#endorsement_detail'>{`${this.currencyType} ${lodashGet(policyDetail, 'payment_detail.total_premium_delta', '-')}`}</a>
            //   },
              {
                name: <a href='#endorsement_detail'><strong>Endorsement Fee</strong></a>,
                value: <a href='#endorsement_detail'>{`${this.currencyType} ${lodashGet(policyDetail, 'Request.endorsement_fee', '-')}`}</a>
              }
            ]
          : []
      ),
      ...(
        lodashGet(policyDetail, 'fleet_discount', '')
          ? [
              {
                name: <strong>Fleet Discount</strong>,
                value: <strong>Rp. {lodashGet(policyDetail, 'fleet_discount', '-')}</strong>
              }
            ]
          : []
      ),
    //   {
    //     name: <strong>Gross Premium</strong>,
    //     value: <strong>{this.currencyType} {lodashGet(policyDetail, (isManualOfflineOrder ? 'net_premium' : 'payment_detail.gross_premium'), '-')}</strong>
    //   },
      {
        name: <strong>Discount</strong>,
        value: `${this.currencyType} ${lodashGet(policyDetail, 'Request.discount_price', '-')}`
      },
    //   ...(
    //     isManualOfflineOrder
    //       ? []
    //       : [{
    //           name: <strong>Net Premium</strong>,
    //           value: <strong>{this.currencyType} {lodashGet(policyDetail, 'payment_detail.net_premium', '-')}</strong>
    //         }]
    //   ),
      {
        name: <strong>Admin Fee</strong>,
        value: `${this.currencyType} ${lodashGet(policyDetail, 'Request.admin_fee', '-')}`
      }, {
        name: <strong>Stamp Duty</strong>,
        value: `${this.currencyType} ${lodashGet(policyDetail, 'Request.stamp_duty', '-')}`
      },
    //   {
    //     name: <strong>Service Fee</strong>,
    //     value: `${this.currencyType} ${lodashGet(policyDetail, 'payment_detail.service_fee', '-')}`
    //   },
      {
        name: <strong>Total Payment</strong>,
        value: <strong>{this.currencyType} {lodashGet(policyDetail, 'Payments[0].Amount', '-')}</strong>
      }
    ]

    return (
      <LayoutContent className='details-info-container policy-detail-card'>
        <Row>
          <h3 className='policy-title'>Payment Details</h3>
          <Col span={24}>
            <Table
              pagination={{
                pageSize: 100
              }}
              showHeader={false}
              columns={columns}
              dataSource={columnPolicyDetailsReq}
            />
          </Col>
        </Row>
      </LayoutContent>
    )
  }
}
const WrappedPolicyDetail = Form.create()(PolicyPaymentDetailCore)
export default connect()(WrappedPolicyDetail)
