  getHardcopyDetails = (details = {}) => {
    const userTimeZone = get(this.props.dataProfile, 'user_timezone', 'UTC')
    const deliveryDate = get(details, 'delivery_date', '')
    const receiveDate = get(details, 'receive_date', '')
    const courierSendTime = get(details, 'courier_send_time', '')
    const courierCompleteTime = get(details, 'courier_complete_time', '')

    const hardcopyDetails = []
    if (get(details, 'proposed_delivery_option', '')) {
      hardcopyDetails.push({
        key: 'detail_1',
        name: 'Propose Delivery Option',
        value: this.getHardcopyDeliveryText(get(details, 'proposed_delivery_option', ''))
      })
    }
    if (get(details, 'courier_partner_order_id', '')) {
      hardcopyDetails.push({
        key: 'detail_2',
        name: 'Airway Bill Number',
        value: get(details, 'courier_partner_order_id', '')
      })
    }
    if (get(details, 'recipient_name', '')) {
      hardcopyDetails.push({
        key: 'detail_3',
        name: 'Recipient Name',
        value: get(details, 'recipient_name', '')
      })
    }
    if (get(details, 'recipient_mobile', '')) {
      hardcopyDetails.push({
        key: 'detail_4',
        name: 'Recipient Contact Number',
        value: get(details, 'recipient_mobile', '')
      })
    }
    if (get(details, 'delivery_type', '')) {
      hardcopyDetails.push({
        key: 'detail_5',
        name: 'Delivery Type',
        value: replaceAgentAndAgencyDash(get(details, 'delivery_type', ''))
      })
    }
    if (courierSendTime) {
      hardcopyDetails.push({
        key: 'detail_5',
        name: 'Courier Send Time',
        value: courierSendTime ? moment(courierSendTime).tz(userTimeZone).format('YYYY-MM-DD HH:mm:ss') : ''
      })
    }
    if (courierCompleteTime) {
      hardcopyDetails.push({
        key: 'detail_5',
        name: 'Courier Complete Time',
        value: courierCompleteTime ? moment(courierCompleteTime).tz(userTimeZone).format('YYYY-MM-DD HH:mm:ss') : ''
      })
    }
    if (deliveryDate) {
      hardcopyDetails.push({
        key: 'detail_6',
        name: 'Pick up date',
        value: deliveryDate ? moment(deliveryDate).tz(userTimeZone).format('YYYY-MM-DD HH:mm:ss') : ''
      })
    }
    if (receiveDate) {
      hardcopyDetails.push({
        key: 'detail_7',
        name: 'Receive from provider',
        value: receiveDate ? moment(receiveDate).tz(userTimeZone).format('YYYY-MM-DD') : ''
      })
    }
    if (get(details, 'courier_label_url', '')) {
      hardcopyDetails.push({
        key: 'detail_8',
        name: 'Courier Label',
        value: this.getCourierPdfContainer(get(details, 'courier_label_url', ''))
      })
    }
    if (get(details, 'remark', '')) {
      hardcopyDetails.push({
        key: 'detail_9',
        name: 'Remark',
        value: get(details, 'remark', '')
      })
    }
    return hardcopyDetails
  }

