  handleCustomRequest = () => {
    const formData = new FormData()
    const fileName = `${get(this.props, 'proofPaymentDetails.request_no', '')}_${Date.parse(new Date())}_${this.file.name}`
    formData.append('file', this.file, fileName)
    formData.append('path', `agent-policy-documents-control-panel/${fileName}`)
    formData.append('identifier', 'agent')
    this.props.uploadPolicyFile({ body: formData })
    this.handleCloseImageModal()
  }

