  disabledDateTime = () => {
    return {
      disabledHours: () => {
        if (moment(this.state.editImageDateTime).startOf('day').isSame(moment().startOf('day'))) {
          return range(moment().hour() + 1, 24)
        } else {
          return []
        }
      },
      disabledMinutes: () => {
        if (moment(this.state.editImageDateTime).startOf('day').isSame(moment().startOf('day'))) {
          return range(moment().minutes() + 1, 60)
        } else {
          return []
        }
      },
      disabledSeconds: () => {
        if (moment(this.state.editImageDateTime).startOf('day').isSame(moment().startOf('day'))) {
          return range(moment().seconds() + 1, 60)
        } else {
          return []
        }
      }
    }
  }

