import React from 'react'
import { connect } from 'react-redux'
import { Row, Col, Table, Form, Modal } from 'antd'
import { get as lodashGet } from 'lodash'
import LayoutContent from '../../../../components/utility/layoutContent'
import { isEmpty, isVNPath } from '../../../../helpers/utility'
import { getAddressString } from '../constants'
import PreventCopy from '../components/PreventCopy'
import moment from 'moment'
import { InvoiceModalStyle } from './components/PaymentInformation/index.style'
class PolicyDetailCoreInfo extends React.Component {
  state = {
    cancelled_doc_url: '',
    showModal: false
  }

  getStatusColor (status) {
    switch (status) {
      case 'ACTIVE':
        return '#2d9600'
      case 'PENDING':
        return '#ffe58f'
      case 'PENDING_EMAIL':
        return '#ffe58f'
      default:
        return ''
    }
  }

  renderInformation (header, detailData) {
    return (
      <Col span={6}>
        <span>{header}</span>
        <p>{detailData}</p>
      </Col>
    )
  }

  renderPolicyStateHeading (policyState) {
    switch (policyState) {
      case 'REJECTED': return 'Rejection'
      case 'CANCELLED': return 'Cancellation'
      default: return ''
    }
  }

  getKeyAccordingToRemark (policyState) {
    switch (policyState) {
      case 'REJECTED': return 'rejected'
      case 'CANCELLED': return 'cancelled'
      default: return ''
    }
  }

  getFormattedName (policyState) {
    if (policyState) {
      return policyState.slice(0, 1).toUpperCase() + policyState.slice(1)
    }
  }

  handleModalOnClick (url) {
    this.setState({
      showModal: true,
      cancelled_doc_url: url
    })
  }

  handleModalOnClose () {
    this.setState({
      showModal: false,
      cancelled_doc_url: ''
    })
  }

  getPolicyRemarkDetailsData (remarkHeading, keyName) {
    const { policyDetail } = this.props
    const remarkDetails = [
      {
        id: 'rejectedPolicyDetail_1',
        name: <strong>{`${remarkHeading} by`}</strong>,
        value: <span className='anchor'>{lodashGet(policyDetail.remark_details?.[keyName], 'processed_by', '-')}</span>
      },
      {
        id: 'rejectedPolicyDetail_2',
        name: <strong>{`${remarkHeading} at`}</strong>,
        value: moment(lodashGet(policyDetail.remark_details?.[keyName], 'created_at', '-')).format('DD MMMM YYYY HH:mm:ss')
      },
      {
        id: 'rejectedPolicyDetail_3',
        name: <strong>Reason</strong>,
        value: lodashGet(policyDetail.remark_details?.[keyName], 'reason', '-')
      }
    ]
    if (keyName === 'reactivated') {
      return remarkDetails
    }

    if (policyDetail.remark_details?.cancelled && lodashGet(policyDetail.remark_details?.cancelled, 'cancellation_documents').length) {
      const availableDocuments = lodashGet(policyDetail.remark_details?.[keyName], 'cancellation_documents')?.map((url, index) => (
        <div className='object-wrapper' key={index} onClick={() => this.handleModalOnClick(url)}>
          <object
            type='application/pdf'
            data={url}
            width={150}
            height={150}
            aria-label='Cancellation Doc Pdf'
            className='clickable-object'
          />
        </div>
      ))
      remarkDetails.push({
        id: 'rejectedPolicyDetail_4',
        name: <strong>Confirmation Letter from Provider</strong>,
        value: availableDocuments
      })
    }

    return remarkDetails
  }

  renderRemarkDetails = (rejectionType, columns, keyName) => {
    const remarkHeading = this.getFormattedName(keyName)
    return (
      <Row className='rejection-details'>
        <h3 className='policy-title'>{`Policy ${rejectionType} Details`}</h3>
        <Col span={24}>
          <Table
            showHeader={false}
            rowKey={data => data.id}
            columns={columns}
            dataSource={this.getPolicyRemarkDetailsData(remarkHeading, keyName)}
          />
        </Col>
      </Row>
    )
  }

  render () {
    const { policyDetail, isTravelProtection } = this.props
    let branchAddress = ''
    // let customerAddr = ''
    // if (!isEmpty(lodashGet(policyDetail, 'customer_address', ''))) {
    //   if (lodashGet(policyDetail, 'customer_address.city_name', '')) {
    //     customerAddr = `${lodashGet(policyDetail, 'customer_address.address')}, ${lodashGet(policyDetail, 'customer_address.city_name')} ${lodashGet(policyDetail, 'customer_address.postal_code')}, ${lodashGet(policyDetail, 'customer_address.province_name')}`
    //   } else {
    //     customerAddr = lodashGet(policyDetail, 'customer_address.address')
    //   }
    // } 
    if (!isEmpty(lodashGet(policyDetail, 'provider_branch', ''))) {
      const addr = getAddressString(
        (policyDetail?.provider_branch?.location && (policyDetail?.provider_branch?.location !== null))
          ? policyDetail?.provider_branch?.location
          : {}
      )
      branchAddress = `${lodashGet(policyDetail, 'provider_branch.name', '')}`
      if (addr) {
        branchAddress = `${branchAddress} - ${addr}`
      }
    }

    const columns = [
      {
        dataIndex: 'name',
        width: 150
      }, {
        dataIndex: 'value'
      }
    ]
    const usePayLater = lodashGet(policyDetail, 'request.use_pay_later', false)
    // const providerPPWDate = lodashGet(policyDetail, 'request.provider_ppw_datetime', '')
    // const agentPPWDate = lodashGet(agentPolicyDetails, 'pay_later_expired_at', '')
    const getKTPNumber = () => {
      if (isTravelProtection) return lodashGet(policyDetail, 'KTP', 0)
      return lodashGet(policyDetail, 'KTP', '-')
    }
    const columnPolicyDetailsReq = [
      {
        id: 'policyDetail_1',
        name: <strong>{isTravelProtection ? 'Policy holder ' : 'Name'}</strong>,
        value: lodashGet(policyDetail, 'Name', '-')
      }, {
        id: 'policyDetail_2',
        name: <strong>{isVNPath() ? 'ID Number' : 'Nomor KTP'}</strong>,
        value: getKTPNumber()
      }, {
        id: 'policyDetail_3',
        name: <strong>Email</strong>,
        value: lodashGet(policyDetail, 'Email', '-')
      }, {
        id: 'policyDetail_4',
        name: <strong>Phone Number</strong>,
        value: lodashGet(policyDetail, 'MobileNo', '-')
      },
      {
        id: 'policyDetail_5',
        name: <strong>Coverage Period</strong>,
        value: `${moment(lodashGet(policyDetail, 'Payments[0].CoverageStartDate', '-')).format('YYYY-MM-DD')} to ${moment(lodashGet(policyDetail, 'Payments[0].CoverageEndDate', '-')).format('YYYY-MM-DD')}`
      }
    //   {
    //     id: 'policyDetail_6',
    //     name: <strong>Pay Later</strong>,
    //     value: usePayLater ? 'Yes' : 'No'
    //   }
    //   ...(
    //     usePayLater
    //       ? [
    //           {
    //             id: 'policyDetail_7',
    //             name: <strong>Payment Due Date by Mitra</strong>,
    //             value: agentPPWDate ? moment(agentPPWDate).format('DD MMMM YYYY') : '-'
    //           },
    //           {
    //             id: 'policyDetail_8',
    //             name: <strong>Payment Due Date to Provider</strong>,
    //             value: providerPPWDate ? moment(providerPPWDate).format('DD MMMM YYYY') : '-'
    //           }
    //         ]
    //       : [])
    ]
    columnPolicyDetailsReq.push({
      id: 'policyDetail_9',
      name: <strong> Customer Address </strong>,
      value: lodashGet(policyDetail, 'Request.address')
    })
    // columnPolicyDetailsReq.push({
    //   id: 'policyDetail_10',
    //   name: <strong> Policy Issuance To </strong>,
    //   value: branchAddress
    // })
    if (lodashGet(policyDetail, 'request.registration_number', '')) {
      columnPolicyDetailsReq.push({
        id: 'policyDetail_11',
        name: <strong> Registration Number(IMO) </strong>,
        value: lodashGet(policyDetail, 'request.registration_number', '-')
      })
    }

    if (isTravelProtection) {
      columnPolicyDetailsReq.push({
        id: 'insured_type',
        name: <strong> Insured Id Type </strong>,
        value: lodashGet(policyDetail, 'request.customer_data.insured_id_type', '-')
      })
    }

    return (
      <PreventCopy>
        <LayoutContent className='details-info-container policy-detail-card'>
          <Row>
            <h3 className='policy-title'>Policy Details</h3>
            <Col span={24}>
              <Table
                pagination={{
                  pageSize: 100
                }}
                showHeader={false}
                rowKey={data => data.id}
                columns={columns}
                dataSource={columnPolicyDetailsReq}
              />
            </Col>
          </Row>
          {
            !isEmpty(policyDetail.remark_details) &&
              <>
                {
                  policyDetail.remark_details?.reactivated &&
                    this.renderRemarkDetails('Reactivation', columns, 'reactivated')
                }
                {
                  policyDetail.remark_details?.cancelled &&
                    this.renderRemarkDetails('Cancellation', columns, 'cancelled')
                }
                {
                  policyDetail.remark_details?.rejected &&
                    this.renderRemarkDetails('Rejection', columns, 'rejected')
                }
              </>
          }
          <Modal
            visible={this.state.showModal}
            onCancel={() => this.handleModalOnClose()}
            style={{ top: 0 }}
            width='100vw'
            footer={null}
          >
            <InvoiceModalStyle>
              <Row type='flex' justify='center'>
                <iframe src={this.state.cancelled_doc_url} title='Confitmation Letter' className='invoice-iframe' />
              </Row>
            </InvoiceModalStyle>
          </Modal>
        </LayoutContent>
      </PreventCopy>
    )
  }
}
const WrappedPolicyDetail = Form.create()(PolicyDetailCoreInfo)
export default connect()(WrappedPolicyDetail)
