import { Button, Modal, Row } from 'antd'
import get from 'lodash/get'
import { useState, useCallback } from 'react'
import ObjectTable from '../ObjectTable'
import { InvoiceModalStyle } from './index.style'
import PropTypes from 'prop-types'
import { replaceAgentAndAgency } from 'opsModule/helpers'
import moment from 'moment'

function PaymentInformationCore (props) {
  const [showInvoiceModal, setShowInvoiceModal] = useState(false)

  const { agentPolicy } = props

  const renderPaymentProofs = useCallback((proofs) => {
    return proofs.map((proof, i) => {
      return (
        <a target='_blank' href={proof.url} key={i} rel='noreferrer'>
          <img className='payment-proof' src={proof.url} alt='payment-proof' />
        </a>
      )
    })
  }, [])

  const getPaymentInformation = useCallback((details = {}) => {
    const isInfoAvailable = agentPolicy?.application_doc_list?.length > 0
    let cols = []
    if (process.env.REACT_APP_IS_INVOICE_ENABLED === 'true') {
      cols = [
        {
          key: 'p_info_1',
          name: 'Invoice',
          value: isInfoAvailable ? <Button onClick={() => { setShowInvoiceModal(true) }}>View</Button> : 'Not Available '
        }
      ]
    }
    cols = [
      ...cols,
      {
        key: 'p_info_1',
        name: 'Payment by',
        value: replaceAgentAndAgency(get(details, 'Payments[0].Partner', '-'))
      },
      {
        key: 'p_info_2',
        name: 'Transfer to',
        value: get(details, 'transfer_to', '-')
      },
      {
        key: 'p_info_3',
        name: 'Transfer amount',
        value: get(details, 'Payments[0].Amount', '-')
      },
      {
        key: 'p_info_4',
        name: 'Payment Date',
        value: moment(get(details, 'Payments[0].PaymentData[0].TxnDate', '-')).format('YYYY-MM-DD')
      },
      {
        key: 'p_info_5',
        name: 'Payment Method',
        value: get(details, 'payment_method', '-')
      },
      {
        key: 'p_info_6',
        name: 'Payment Proof',
        value: (
          get(details, 'payment_proof', '')
            ? renderPaymentProofs(get(details, 'payment_proof', ''))
            : '-'
        )
      }
    ]
    return cols
  }, [agentPolicy, renderPaymentProofs])

  return (
    <>
      <ObjectTable
        title='Payment Information'
        tableColumns={getPaymentInformation(agentPolicy)}
      />
      <Modal
        visible={showInvoiceModal}
        onOk={() => setShowInvoiceModal(false)}
        onCancel={() => setShowInvoiceModal(false)}
        style={{ top: 0 }}
        width='100vw'
        footer={null}
      >
        <InvoiceModalStyle>
          <Row type='flex' justify='center'>
            {
              agentPolicy?.application_doc_list &&
                <iframe src={agentPolicy?.application_doc_list[0]} title='Invoice' className='invoice-iframe' />
            }
          </Row>
        </InvoiceModalStyle>
      </Modal>
    </>
  )
}

PaymentInformationCore.propTypes = {
  agentPolicy: PropTypes.object
}

export default PaymentInformationCore
